abstract contract ResourceMetering_TestInit is Test {
    MeterUser internal meter;
    uint64 initialBlockNum;

    /// @notice Sets up the test contract.
    function setUp() public {
        meter = new MeterUser();
        initialBlockNum = uint64(block.number);
    }
}

