    ISuperchainTokenBridge public superchainTokenBridge;

    /// @notice Sets up the test suite.
    function setUp() public {
        vm.etch(Predeploys.SUPERCHAIN_TOKEN_BRIDGE, address(new SuperchainTokenBridge()).code);
