        assertEq(delayedWeth.proxyAdminOwner(), proxyAdminOwner);
        assertEq(address(delayedWeth.systemConfig()), address(systemConfig));
        assertEq(address(delayedWeth.config()), address(systemConfig.superchainConfig()));
    }

