                initCalldata: abi.encodeCall(IFeeVault.initialize, (address(0), 0, Types.WithdrawalNetwork.L1))
            })
        );

        // OperatorFeeVault
        contracts.push(
            InitializeableContract({
                target: address(
                    DeployUtils.create1({
                        _name: "OperatorFeeVault",
